@app.route("/")
def home():
    carrinho = session.get("carrinho", {})

    if not isinstance(carrinho, dict):
        carrinho = {}
        session["carrinho"] = carrinho

    total_itens = 0
    for quantidade in carrinho.values():
        try:
            total_itens += int(quantidade)
        except (ValueError, TypeError):
            pass

    categoria = request.args.get("categoria", "Todos")

    if categoria == "Todos":
        produtos_exibidos = PRODUTOS
    else:
        produtos_exibidos = [
            produto for produto in PRODUTOS
            if produto["categoria"] == categoria
        ]

    return render_template(
        "index.html",
        lista_produtos=produtos_exibidos,
        total_itens=total_itens,
        categorias=CATEGORIAS,
        categoria_atual=categoria
    )


@app.route("/adicionar/<int:produto_id>")
def adicionar(produto_id):

    if not isinstance(session.get("carrinho"), dict):
        session["carrinho"] = {}

    carrinho = session["carrinho"]

    chave = str(produto_id)

    carrinho[chave] = carrinho.get(chave, 0) + 1

    session["carrinho"] = carrinho

    session.modified = True


    if request.args.get("origem") == "carrinho":

        return redirect(url_for("carrinho"))

    return redirect(url_for("home"))


@app.route("/diminuir/<int:produto_id>")
def diminuir(produto_id):
    carrinho = session.get("carrinho", {})

    if not isinstance(carrinho, dict):
        carrinho = {}

    chave = str(produto_id)

    if chave in carrinho:
        try:
            quantidade = int(carrinho[chave])
        except (ValueError, TypeError):
            quantidade = 0

        quantidade -= 1

        if quantidade <= 0:
            carrinho.pop(chave, None)
        else:
            carrinho[chave] = quantidade

    session["carrinho"] = carrinho
    session.modified = True

    return redirect(url_for("carrinho"))


@app.route("/remover/<int:produto_id>")
def remover(produto_id):
    carrinho = session.get("carrinho", {})

    if not isinstance(carrinho, dict):
        carrinho = {}

    carrinho.pop(str(produto_id), None)

    session["carrinho"] = carrinho
    session.modified = True

    return redirect(url_for("carrinho"))


@app.route("/carrinho")
def carrinho():
    carrinho_session = session.get("carrinho", {})

    if not isinstance(carrinho_session, dict):
        carrinho_session = {}

    itens = []
    total = 0.0
    total_itens = 0

    for produto in PRODUTOS:
        chave = str(produto["id"])

        try:
            quantidade = int(carrinho_session.get(chave, 0))
        except (ValueError, TypeError):
            quantidade = 0

        if quantidade <= 0:
            continue

        try:
            preco = float(produto["preco"])
        except (ValueError, TypeError):
            preco = 0.0

        subtotal = preco * quantidade

        itens.append({
            "produto": produto,
            "quantidade": quantidade,
            "preco": preco,
            "subtotal": subtotal
        })

        total += subtotal
        total_itens += quantidade

    return render_template(
        "carrinho.html",
        itens=itens,
        total=total,
        total_itens=total_itens
    )


@app.route("/limpar")
def limpar():
    session["carrinho"] = {}
    session.modified = True
    return redirect(url_for("home"))


@app.route("/finalizar")
def finalizar():
    carrinho_session = session.get("carrinho", {})

    if not isinstance(carrinho_session, dict):
        carrinho_session = {}

    itens = []
    total = 0.0

    for produto in PRODUTOS:
        chave = str(produto["id"])

        try:
            quantidade = int(carrinho_session.get(chave, 0))
        except (ValueError, TypeError):
            quantidade = 0

        if quantidade <= 0:
            continue

        preco = float(produto["preco"])
        subtotal = preco * quantidade

        itens.append({
            "produto": produto,
            "quantidade": quantidade,
            "preco": preco,
            "subtotal": subtotal
        })

        total += subtotal

    return render_template(
        "pedido.html",
        itens=itens,
        total=total
    )


@app.route("/enviar_pedido", methods=["POST"])
def enviar_pedido():
    carrinho_session = session.get("carrinho", {})

    if not isinstance(carrinho_session, dict):
        carrinho_session = {}

    partes = []
    total = 0.0

    for produto in PRODUTOS:
        chave = str(produto["id"])

        try:
            quantidade = int(carrinho_session.get(chave, 0))
        except (ValueError, TypeError):
            quantidade = 0

        if quantidade <= 0:
            continue

        preco = float(produto["preco"])
        subtotal = preco * quantidade
        total += subtotal

        partes.append(
            f"{quantidade}x {produto['nome']} - R$ {subtotal:.2f}"
        )

    if not partes:
        return redirect(url_for("home"))

    mensagem = "Olá! Gostaria de fazer este pedido:\n\n"
    mensagem += "\n".join(partes)
    mensagem += f"\n\nTotal dos produtos: R$ {total:.2f}"

    mensagem += (
        "\n\n⚠️ AVISO IMPORTANTE:"
        "\nOs valores apresentados no carrinho correspondem aos produtos selecionados."
        "\nO valor final poderá sofrer alterações devido ao frete, entrega ou distância do endereço."
        "\nO valor da entrega será confirmado no momento da finalização do pedido pelo WhatsApp."
    )

    numero = "5565993160255"
    link = f"https://wa.me/{numero}?text={quote(mensagem)}"

    return redirect(link)


